package com.bankstats;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;

@ConfigGroup("bankstats")
public interface BankStatsConfig extends Config
{
}

package com.bankstats;

import com.bankstats.controller.BankStatsController;
import com.google.inject.Provides;
import javax.inject.Inject;
import net.runelite.api.InventoryID;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.eventbus.Subscribe;

@PluginDescriptor(
    name = "Bank Stats",
    description = "Tracks changes in bank item values over time"
)
public class BankStatsPlugin extends Plugin
{
    @Inject
    private BankStatsController controller;

    @Inject
    private ClientToolbar clientToolbar;

    private NavigationButton navigationButton;

    @Override
    protected void startUp()
    {
        navigationButton = controller.createNavigationButton();
        clientToolbar.addNavigation(navigationButton);
        controller.start();
    }

    @Override
    protected void shutDown()
    {
        controller.stop();

        if (navigationButton != null)
        {
            clientToolbar.removeNavigation(navigationButton);
            navigationButton = null;
        }
    }

    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event)
    {
        if (event.getContainerId() == InventoryID.BANK.getId())
        {
            controller.onBankChanged(event.getItemContainer());
        }
    }

    @Subscribe
    public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
    {
        controller.onProfileChanged();
    }

    @Provides
    BankStatsConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(BankStatsConfig.class);
    }
}

package com.bankstats.analysis;

@FunctionalInterface
public interface AnalysisProgressListener
{
    void onProgress(int analyzedItems, int totalItems);
}

package com.bankstats.analysis;

import com.bankstats.model.BankAnalysis;
import com.bankstats.model.BankSnapshot;
import com.bankstats.model.BaselineData;
import com.bankstats.model.PriceBook;
import com.google.inject.ImplementedBy;

@ImplementedBy(DefaultBankAnalyzer.class)
public interface BankAnalyzer
{
