package com.bankstats.analysis;

import com.bankstats.model.BankAnalysis;
import com.bankstats.model.BankSnapshot;
import com.bankstats.model.BaselineData;
import com.bankstats.model.BaselineItem;
import com.bankstats.model.ItemPerformance;
import com.bankstats.model.PriceBook;
import com.bankstats.model.PriceQuote;
import com.bankstats.model.PriceStatus;
import com.bankstats.price.ValuationPolicy;
import java.time.Instant;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;

@Singleton
public class DefaultBankAnalyzer implements BankAnalyzer
{
    private final ValuationPolicy valuationPolicy;

    @Inject
    public DefaultBankAnalyzer(ValuationPolicy valuationPolicy)
    {
        this.valuationPolicy = valuationPolicy;
    }

    @Override
    public BankAnalysis analyze(BaselineData baseline, BankSnapshot currentBank, PriceBook currentPrices)
    {
        return analyze(baseline, currentBank, currentPrices, null);
    }

    @Override
    public BankAnalysis analyze(
        BaselineData baseline,
        BankSnapshot currentBank,
        PriceBook currentPrices,
        AnalysisProgressListener progressListener)
    {
        BaselineData safeBaseline = baseline == null ? BaselineData.empty() : baseline;
        Set<Integer> itemIds = new HashSet<>(safeBaseline.getItems().keySet());
        itemIds.addAll(currentBank.getItemIds());

        List<ItemPerformance> rows = new ArrayList<>();
        long totalCurrentValue = 0;
        long totalMarketProfitLoss = 0;
        long totalPositionChange = 0;
        int analyzedItems = 0;
        int totalItems = itemIds.size();

        notifyProgress(progressListener, analyzedItems, totalItems);

        for (int itemId : itemIds)
        {
            BaselineItem baselineItem = safeBaseline.getItem(itemId);
            PriceQuote currentQuote = currentPrices.getPrice(itemId);

            long baselineQuantity = baselineItem == null ? 0 : baselineItem.getQuantity();
            long currentQuantity = currentBank.getQuantity(itemId);
            long baselineUnitPrice = baselineItem == null ? 0 : baselineItem.getUnitPrice();
            long currentUnitPrice = currentQuote == null || !currentQuote.hasPrice() ? 0 : valuationPolicy.getUnitPrice(currentQuote);
            PriceStatus status = getStatus(baselineItem, currentQuote);

            long baselineValue = baselineQuantity * baselineUnitPrice;
            long currentValue = status == PriceStatus.MISSING_CURRENT_PRICE ? 0 : currentQuantity * currentUnitPrice;
            long unitPriceChange = currentUnitPrice - baselineUnitPrice;
            double percentPriceChange = baselineUnitPrice == 0 ? 0 : ((double) unitPriceChange / baselineUnitPrice) * 100.0;
            long marketProfitLoss = status == PriceStatus.PRICED ? currentQuantity * unitPriceChange : 0;
            long positionChange = status == PriceStatus.MISSING_CURRENT_PRICE ? 0 : currentValue - baselineValue;

            rows.add(new ItemPerformance(itemId, baselineQuantity, currentQuantity, baselineUnitPrice, currentUnitPrice,
                baselineValue, currentValue, unitPriceChange, percentPriceChange, marketProfitLoss, positionChange, status));

            totalCurrentValue += currentValue;
            totalMarketProfitLoss += marketProfitLoss;
            totalPositionChange += positionChange;
            analyzedItems++;

            if (shouldNotifyProgress(analyzedItems, totalItems))
            {
                notifyProgress(progressListener, analyzedItems, totalItems);
            }
        }

        rows.sort((left, right) -> Long.compare(right.getTotalPositionChange(), left.getTotalPositionChange()));
        return new BankAnalysis(Instant.now(), safeBaseline.getCreatedAt(), rows, safeBaseline.getBaselineValue(), totalCurrentValue, totalMarketProfitLoss, totalPositionChange);
    }

    private boolean shouldNotifyProgress(int analyzedItems, int totalItems)
    {
        return analyzedItems == totalItems || analyzedItems % 25 == 0;
    }

    private void notifyProgress(AnalysisProgressListener progressListener, int analyzedItems, int totalItems)
    {
        if (progressListener != null)
        {
            progressListener.onProgress(analyzedItems, totalItems);
        }
    }

    private PriceStatus getStatus(BaselineItem baselineItem, PriceQuote currentQuote)
    {
        if (baselineItem == null || baselineItem.getUnitPrice() <= 0)
        {
            return PriceStatus.MISSING_BASELINE_PRICE;
        }

        if (currentQuote == null || !currentQuote.hasPrice())
        {
            return PriceStatus.MISSING_CURRENT_PRICE;
        }

        return PriceStatus.PRICED;
    }
}

package com.bankstats.bank;

import com.bankstats.model.BankSnapshot;

public class BankCaptureResult
{
    private final BankSnapshot snapshot;
    private final String message;

    private BankCaptureResult(BankSnapshot snapshot, String message)
    {
        this.snapshot = snapshot;
        this.message = message;
    }

    public static BankCaptureResult success(BankSnapshot snapshot)
    {
        return new BankCaptureResult(snapshot, null);
    }

    public static BankCaptureResult bankNotOpen()
    {
        return new BankCaptureResult(null, "Open your bank before loading Bank Stats.");
    }

    public boolean isSuccess()
    {
        return snapshot != null;
    }

    public BankSnapshot getSnapshot()
    {
        return snapshot;
    }

    public String getMessage()
    {
        return message;
    }
}

