package com.bankstats.bank;

import com.bankstats.model.BankSnapshot;
import java.time.Instant;
import java.util.HashMap;
import java.util.Map;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.client.callback.ClientThread;

@Singleton
public class RuneLiteBankReader implements BankReader
{
    private final Client client;
    private final ClientThread clientThread;
    private final ItemIdentityStrategy itemIdentityStrategy;

    @Inject
    public RuneLiteBankReader(Client client, ClientThread clientThread, ItemIdentityStrategy itemIdentityStrategy)
    {
        this.client = client;
        this.clientThread = clientThread;
        this.itemIdentityStrategy = itemIdentityStrategy;
    }

    @Override
    public void captureBank(Consumer<BankCaptureResult> callback)
    {
        clientThread.invokeLater(() ->
        {
            ItemContainer bank = client.getItemContainer(InventoryID.BANK);
            if (bank == null)
            {
                callback.accept(BankCaptureResult.bankNotOpen());
                return;
            }

            Map<Integer, Long> quantities = new HashMap<>();
            for (Item item : bank.getItems())
            {
                if (item.getId() <= 0 || item.getQuantity() <= 0 || isPlaceholder(item.getId()))
                {
                    continue;
                }

                int trackingId = itemIdentityStrategy.getTrackingId(item.getId());
                quantities.merge(trackingId, (long) item.getQuantity(), Long::sum);
            }

            callback.accept(BankCaptureResult.success(new BankSnapshot(Instant.now(), quantities)));
        });
    }

    private boolean isPlaceholder(int itemId)
    {
        ItemComposition itemComposition = client.getItemDefinition(itemId);
        return itemComposition.getPlaceholderTemplateId() != -1;
    }
}

package com.bankstats.bank;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.game.ItemManager;

@Singleton
public class RuneLiteItemIdentityStrategy implements ItemIdentityStrategy
{
    private final ItemManager itemManager;

    @Inject
    public RuneLiteItemIdentityStrategy(ItemManager itemManager)
    {
        this.itemManager = itemManager;
    }

    @Override
    public int getTrackingId(int rawItemId)
    {
        return itemManager.canonicalize(rawItemId);
    }
}

package com.bankstats.controller;

import com.bankstats.BankStatsPlugin;
import com.bankstats.analysis.BankAnalyzer;
import com.bankstats.bank.BankReader;
import com.bankstats.model.BankAnalysis;
import com.bankstats.model.BankSnapshot;
import com.bankstats.model.BaselineData;
import com.bankstats.model.BaselineItem;
import com.bankstats.model.LoadState;
import com.bankstats.model.PriceBook;
import com.bankstats.model.PriceQuote;
import com.bankstats.persistence.BaselineRepository;
import com.bankstats.price.PriceProvider;
import com.bankstats.price.ValuationPolicy;
import com.bankstats.ui.BankStatsPanel;
import java.awt.image.BufferedImage;
import java.time.Instant;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.atomic.AtomicLong;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import net.runelite.api.ItemContainer;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.Text;

@Singleton
public class BankStatsController
{
    private final BankReader bankReader;
    private final PriceProvider priceProvider;
    private final ValuationPolicy valuationPolicy;
    private final BankAnalyzer bankAnalyzer;
    private final BaselineRepository baselineRepository;
    private final BankStatsPanel panel;
    private final AtomicLong generation = new AtomicLong();

    private BankSnapshot currentSnapshot;

    @Inject
    public BankStatsController(
        BankReader bankReader,
        PriceProvider priceProvider,
        ValuationPolicy valuationPolicy,
        BankAnalyzer bankAnalyzer,
        BaselineRepository baselineRepository,
        BankStatsPanel panel)
    {
        this.bankReader = bankReader;
        this.priceProvider = priceProvider;
        this.valuationPolicy = valuationPolicy;
        this.bankAnalyzer = bankAnalyzer;
        this.baselineRepository = baselineRepository;
        this.panel = panel;
    }

    public void start()
    {
        panel.setCreateBaselineAction(this::setBaselineFromBank);
        panel.setLoadBankAction(this::loadFromBank);
        panel.setRefreshPricesAction(this::refreshPrices);
        panel.setLoadState(LoadState.READY_TO_LOAD, "Open your bank to begin.");
    }

    public void stop()
    {
        generation.incrementAndGet();
        currentSnapshot = null;
    }

    public NavigationButton createNavigationButton()
    {
        BufferedImage icon = ImageUtil.loadImageResource(BankStatsPlugin.class, "/com/bankstats/icon.png");

        return NavigationButton.builder()
            .tooltip("Bank Stats")
            .icon(icon)
            .priority(5)
            .panel(panel)
            .build();
    }

    public void onBankChanged(ItemContainer itemContainer)
    {
        panel.setLoadState(itemContainer == null ? LoadState.NO_BANK : LoadState.READY_TO_LOAD, null);
    }

    public void onProfileChanged()
    {
        generation.incrementAndGet();
        currentSnapshot = null;
        panel.clearAnalysis();
        panel.setLoadState(LoadState.READY_TO_LOAD, "Profile changed. Load your bank again.");
    }

    public void setBaselineFromBank()
    {
        try
        {
            BaselineData existingBaseline = baselineRepository.load();
            if (!existingBaseline.getItems().isEmpty() && !panel.confirmOverwriteBaseline())
            {
                return;
            }
        }
        catch (RuntimeException ex)
        {
            showError(formatError("Unable to check current baseline", ex));
            return;
        }

        long requestId = generation.incrementAndGet();
        panel.setLoadState(LoadState.READING_BANK, "Reading bank...");

        bankReader.captureBank(result ->
        {
            if (!isCurrent(requestId))
            {
                return;
            }

            if (!result.isSuccess())
            {
                showError(result.getMessage());
                return;
            }

            BankSnapshot snapshot = result.getSnapshot();
            if (snapshot.getItemIds().isEmpty())
            {
                showError("Your bank snapshot is empty.");
                return;
            }

            panel.setLoadState(LoadState.LOADING_PRICES, "Loading prices...");
            priceProvider.getPrices(snapshot.getItemIds()).whenComplete((prices, error) ->
            {
                if (!isCurrent(requestId))
                {
                    return;
                }

                if (error != null)
                {
                    showError(formatError("Unable to load prices", error));
                    return;
                }

                try
                {
                    BaselineData baseline = createBaseline(snapshot, prices);
                    if (baseline.getItems().isEmpty())
                    {
                        showError("No priced items were found in your bank.");
                        return;
                    }

                    baselineRepository.save(baseline);
                    currentSnapshot = snapshot;
                    analyzeCurrent(requestId, snapshot, prices, baseline);
                }
                catch (RuntimeException ex)
                {
                    showError(formatError("Unable to save baseline", ex));
                }
            });
        });
    }

    public void loadFromBank()
    {
        long requestId = generation.incrementAndGet();
        panel.setLoadState(LoadState.READING_BANK, "Reading bank...");

        bankReader.captureBank(result ->
        {
            if (!isCurrent(requestId))
            {
                return;
            }

            if (!result.isSuccess())
            {
                showError(result.getMessage());
                return;
            }

            BankSnapshot snapshot = result.getSnapshot();
            if (snapshot.getItemIds().isEmpty())
            {
                showError("Your bank snapshot is empty.");
                return;
            }

            currentSnapshot = snapshot;
            loadPricesAndAnalyze(requestId, snapshot, true);
        });
    }

    public void refreshPrices()
    {
        BankSnapshot snapshot = currentSnapshot;
        if (snapshot == null)
        {
            loadFromBank();
            return;
        }

        long requestId = generation.incrementAndGet();
        loadPricesAndAnalyze(requestId, snapshot, false);
    }

    private void loadPricesAndAnalyze(long requestId, BankSnapshot snapshot, boolean rebaseBaselineQuantities)
    {
        panel.setLoadState(LoadState.LOADING_PRICES, "Loading prices...");
        priceProvider.getPrices(snapshot.getItemIds()).whenComplete((prices, error) ->
        {
            if (!isCurrent(requestId))
            {
                return;
            }

            if (error != null)
            {
                showError(formatError("Unable to load prices", error));
                return;
            }

            try
            {
                BaselineData baseline = baselineRepository.load();
                if (rebaseBaselineQuantities)
                {
                    BaselineRebaseResult rebaseResult = rebaseBaselineForCurrentBank(baseline, snapshot, prices);
                    baseline = rebaseResult.getBaseline();
                    if (rebaseResult.isChanged())
                    {
                        baselineRepository.save(baseline);
                    }
                }

                analyzeCurrent(requestId, snapshot, prices, baseline);
            }
            catch (RuntimeException ex)
            {
                showError(formatError("Unable to load baseline", ex));
            }
        });
    }

    private void analyzeCurrent(long requestId, BankSnapshot snapshot, PriceBook prices, BaselineData baseline)
    {
        panel.setLoadState(LoadState.ANALYZING, "Analyzing bank...");
        BankAnalysis analysis = bankAnalyzer.analyze(baseline, snapshot, prices,
            (analyzedItems, totalItems) -> updateAnalysisProgress(requestId, analyzedItems, totalItems));

        updateUi(requestId, () ->
        {
            try
            {
                panel.showAnalysisReady(analysis.getRows().size());
                panel.displayAnalysis(analysis);
                panel.setLoadState(LoadState.COMPLETE, "Displayed " + analysis.getRows().size() + " analyzed rows.");
            }
            catch (RuntimeException ex)
            {
                panel.showDisplayError(formatError("Unable to display analysis", ex), analysis);
                panel.setLoadState(LoadState.ERROR, "Unable to display analysis.");
            }
        });
    }

    private BaselineData createBaseline(BankSnapshot snapshot, PriceBook prices)
    {
        Map<Integer, BaselineItem> items = new HashMap<>();

        for (Map.Entry<Integer, Long> entry : snapshot.getQuantities().entrySet())
        {
            PriceQuote quote = prices.getPrice(entry.getKey());
            if (quote == null || !quote.hasPrice())
            {
                continue;
            }

            items.put(entry.getKey(), new BaselineItem(entry.getKey(), entry.getValue(), valuationPolicy.getUnitPrice(quote)));
        }

        return new BaselineData(BaselineData.CURRENT_SCHEMA_VERSION, Instant.now(), valuationPolicy.getId(), items);
    }

    private BaselineRebaseResult rebaseBaselineForCurrentBank(BaselineData baseline, BankSnapshot snapshot, PriceBook prices)
    {
        BaselineData safeBaseline = baseline == null ? BaselineData.empty() : baseline;
        if (safeBaseline.getItems().isEmpty())
        {
            return new BaselineRebaseResult(safeBaseline, false);
        }

        Map<Integer, BaselineItem> rebasedItems = new HashMap<>();
        boolean changed = false;

        for (Map.Entry<Integer, Long> entry : snapshot.getQuantities().entrySet())
        {
            int itemId = entry.getKey();
            long currentQuantity = entry.getValue();
            BaselineItem baselineItem = safeBaseline.getItem(itemId);

            if (baselineItem != null)
            {
                long rebasedUnitPrice = getRebasedUnitPrice(baselineItem, currentQuantity, prices.getPrice(itemId));
                if (baselineItem.getQuantity() != currentQuantity || baselineItem.getUnitPrice() != rebasedUnitPrice)
                {
                    changed = true;
                }

                rebasedItems.put(itemId, new BaselineItem(itemId, currentQuantity, rebasedUnitPrice));
                continue;
            }

            PriceQuote quote = prices.getPrice(itemId);
            if (quote == null || !quote.hasPrice())
            {
                continue;
            }

            changed = true;
            rebasedItems.put(itemId, new BaselineItem(itemId, currentQuantity, valuationPolicy.getUnitPrice(quote)));
        }

        for (int itemId : safeBaseline.getItems().keySet())
        {
            if (!snapshot.getItemIds().contains(itemId))
            {
                changed = true;
                break;
            }
        }

        if (!changed)
        {
            return new BaselineRebaseResult(safeBaseline, false);
        }

        return new BaselineRebaseResult(new BaselineData(
            BaselineData.CURRENT_SCHEMA_VERSION,
            safeBaseline.getCreatedAt(),
            safeBaseline.getPricingMethod(),
            rebasedItems,
            safeBaseline.getBaselineValue()), true);
    }

    private long getRebasedUnitPrice(BaselineItem baselineItem, long currentQuantity, PriceQuote currentQuote)
    {
        long baselineQuantity = baselineItem.getQuantity();
        long baselineUnitPrice = baselineItem.getUnitPrice();
        if (currentQuantity <= baselineQuantity || currentQuote == null || !currentQuote.hasPrice())
        {
            return baselineUnitPrice;
        }

        long addedQuantity = currentQuantity - baselineQuantity;
        long currentUnitPrice = valuationPolicy.getUnitPrice(currentQuote);
        double totalRebasedValue = (baselineQuantity * (double) baselineUnitPrice) + (addedQuantity * (double) currentUnitPrice);
        return Math.round(totalRebasedValue / currentQuantity);
    }

    private void updateAnalysisProgress(long requestId, int analyzedItems, int totalItems)
    {
        if (!isCurrent(requestId))
        {
            return;
        }

        int remainingItems = Math.max(0, totalItems - analyzedItems);
        String message = String.format("Analyzing bank: %d / %d items (%d left)", analyzedItems, totalItems, remainingItems);
        updateUi(requestId, () -> panel.setLoadState(LoadState.ANALYZING, message));
    }

    private void updateUi(long requestId, Runnable action)
    {
        if (!isCurrent(requestId))
        {
            return;
        }

        if (SwingUtilities.isEventDispatchThread())
        {
            action.run();
            return;
        }

        SwingUtilities.invokeLater(() ->
        {
            if (isCurrent(requestId))
            {
                action.run();
            }
        });
    }

    private boolean isCurrent(long requestId)
    {
        return generation.get() == requestId;
    }

    private String formatError(String message, Throwable error)
    {
        Throwable cause = error.getCause() == null ? error : error.getCause();
        String detail = cause.getMessage();
        if (detail == null || detail.isEmpty())
        {
            detail = cause.getClass().getSimpleName();
        }

        return message + ": " + Text.removeTags(detail);
    }

    private void showError(String message)
    {
        SwingUtilities.invokeLater(() -> panel.setLoadState(LoadState.ERROR, message));
    }

    private static class BaselineRebaseResult
    {
        private final BaselineData baseline;
        private final boolean changed;

        private BaselineRebaseResult(BaselineData baseline, boolean changed)
        {
            this.baseline = baseline;
            this.changed = changed;
        }

        private BaselineData getBaseline()
        {
            return baseline;
        }

        private boolean isChanged()
        {
            return changed;
        }
    }
}

package com.bankstats.model;

import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class BankAnalysis
{
    private final Instant analyzedAt;
    private final Instant baselineCreatedAt;
    private final List<ItemPerformance> rows;
    private final long baselineValue;
    private final long currentValue;
    private final long marketProfitLoss;
    private final long totalPositionChange;

    public BankAnalysis(
        Instant analyzedAt,
        Instant baselineCreatedAt,
        List<ItemPerformance> rows,
        long baselineValue,
        long currentValue,
        long marketProfitLoss,
        long totalPositionChange)
    {
        this.analyzedAt = analyzedAt;
        this.baselineCreatedAt = baselineCreatedAt;
        this.rows = Collections.unmodifiableList(new ArrayList<>(rows));
        this.baselineValue = baselineValue;
        this.currentValue = currentValue;
        this.marketProfitLoss = marketProfitLoss;
        this.totalPositionChange = totalPositionChange;
    }

    public Instant getAnalyzedAt()
    {
        return analyzedAt;
    }

    public Instant getBaselineCreatedAt()
    {
        return baselineCreatedAt;
    }

    public List<ItemPerformance> getRows()
    {
        return rows;
    }

    public long getBaselineValue()
    {
        return baselineValue;
    }

    public long getCurrentValue()
    {
        return currentValue;
    }

    public long getMarketProfitLoss()
    {
        return marketProfitLoss;
    }

    public long getTotalPositionChange()
    {
        return totalPositionChange;
    }
}

