}

package com.bankstats.model;

import java.time.Instant;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;

public class BankSnapshot
{
    private final Instant capturedAt;
    private final Map<Integer, Long> quantities;

    public BankSnapshot(Instant capturedAt, Map<Integer, Long> quantities)
    {
        this.capturedAt = capturedAt;
        this.quantities = Collections.unmodifiableMap(new HashMap<>(quantities));
    }

    public Instant getCapturedAt()
    {
        return capturedAt;
    }

    public Map<Integer, Long> getQuantities()
    {
        return quantities;
    }

    public Set<Integer> getItemIds()
    {
        return quantities.keySet();
    }

    public long getQuantity(int itemId)
    {
        return quantities.getOrDefault(itemId, 0L);
    }
}

package com.bankstats.model;

import java.time.Instant;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

public class BaselineData
{
    public static final int CURRENT_SCHEMA_VERSION = 1;

    private int schemaVersion;
    private String createdAt;
    private String pricingMethod;
    private long baselineValue;
    private Map<Integer, BaselineItem> items;

    public BaselineData()
    {
        items = new HashMap<>();
    }

    public BaselineData(int schemaVersion, Instant createdAt, String pricingMethod, Map<Integer, BaselineItem> items)
    {
        this(schemaVersion, createdAt, pricingMethod, items, calculateBaselineValue(items));
    }

    public BaselineData(int schemaVersion, Instant createdAt, String pricingMethod, Map<Integer, BaselineItem> items, long baselineValue)
    {
        this.schemaVersion = schemaVersion;
        this.createdAt = createdAt.toString();
        this.pricingMethod = pricingMethod;
        this.baselineValue = baselineValue;
        this.items = new HashMap<>(items);
    }

    public static BaselineData empty()
    {
        return new BaselineData(CURRENT_SCHEMA_VERSION, Instant.EPOCH, "none", Collections.emptyMap());
    }

    public int getSchemaVersion()
    {
        return schemaVersion;
    }

    public Instant getCreatedAt()
    {
        return createdAt == null ? Instant.EPOCH : Instant.parse(createdAt);
    }

    public String getPricingMethod()
    {
        return pricingMethod;
    }

    public long getBaselineValue()
    {
        return baselineValue > 0 ? baselineValue : calculateBaselineValue(getItems());
    }

    public Map<Integer, BaselineItem> getItems()
    {
        return Collections.unmodifiableMap(items == null ? Collections.emptyMap() : items);
    }

    public BaselineItem getItem(int itemId)
    {
        return items == null ? null : items.get(itemId);
    }

    private static long calculateBaselineValue(Map<Integer, BaselineItem> items)
    {
        if (items == null)
        {
            return 0;
        }

        long total = 0;
        for (BaselineItem item : items.values())
        {
            total += item.getQuantity() * item.getUnitPrice();
        }

        return total;
    }
}

