package com.bankstats.persistence;

import com.bankstats.model.BaselineData;
import com.google.gson.Gson;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

@Singleton
public class ConfigBaselineRepository implements BaselineRepository
{
    private static final String CONFIG_GROUP = "bankstats";
    private static final String BASELINE_KEY = "baseline";

    private final ConfigManager configManager;
    private final Gson gson;

    @Inject
    public ConfigBaselineRepository(ConfigManager configManager, Gson gson)
    {
        this.configManager = configManager;
        this.gson = gson;
    }

    @Override
    public BaselineData load()
    {
        String json = configManager.getRSProfileConfiguration(CONFIG_GROUP, BASELINE_KEY);
        if (json == null || json.isEmpty())
        {
            return BaselineData.empty();
        }

        BaselineData baseline = gson.fromJson(json, BaselineData.class);
        if (baseline.getSchemaVersion() != BaselineData.CURRENT_SCHEMA_VERSION)
        {
            throw new UnsupportedBaselineVersionException(baseline.getSchemaVersion());
        }

        return baseline;
    }

    @Override
    public void save(BaselineData baseline)
    {
        configManager.setRSProfileConfiguration(CONFIG_GROUP, BASELINE_KEY, gson.toJson(baseline));
    }

    @Override
    public void delete()
    {
        configManager.unsetRSProfileConfiguration(CONFIG_GROUP, BASELINE_KEY);
    }
}

