import com.bankstats.model.PriceQuote;

public class AveragePricePolicy implements ValuationPolicy
{
    @Override
    public long getUnitPrice(PriceQuote quote)
    {
        long high = quote.getHighPrice();
        long low = quote.getLowPrice();

        if (high <= 0)
        {
            return low;
        }

        if (low <= 0)
        {
            return high;
        }

        return (high + low) / 2;
    }

    @Override
    public String getId()
    {
        return "high-low-average-v1";
    }
}

