import java.time.Instant;
import java.util.Set;
import javax.inject.Singleton;

@Singleton
public class PriceCache
{
    private static final Duration DEFAULT_TTL = Duration.ofSeconds(75);

    private PriceBook priceBook;
    private Instant expiresAt = Instant.EPOCH;

    public synchronized PriceBook getIfFresh(Set<Integer> itemIds)
    {
        if (priceBook == null || Instant.now().isAfter(expiresAt) || !priceBook.getPrices().keySet().containsAll(itemIds))
        {
            return null;
        }

        return priceBook;
    }

    public synchronized void put(PriceBook priceBook)
    {
        this.priceBook = priceBook;
        expiresAt = Instant.now().plus(DEFAULT_TTL);
    }

    public synchronized void clear()
    {
        priceBook = null;
        expiresAt = Instant.EPOCH;
    }
}

