package com.bankstats.price;

import com.bankstats.model.PriceBook;
import com.bankstats.model.PriceQuote;
import java.time.Instant;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.CompletableFuture;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;

@Singleton
public class RuneLitePriceProvider implements PriceProvider
{
    private final ClientThread clientThread;
    private final ItemManager itemManager;

    @Inject
    public RuneLitePriceProvider(ClientThread clientThread, ItemManager itemManager)
    {
        this.clientThread = clientThread;
        this.itemManager = itemManager;
    }

    @Override
    public CompletableFuture<PriceBook> getPrices(Set<Integer> itemIds)
    {
        CompletableFuture<PriceBook> future = new CompletableFuture<>();

        clientThread.invokeLater(() ->
        {
            try
            {
                Instant retrievedAt = Instant.now();
                Map<Integer, PriceQuote> prices = new HashMap<>();

                for (int itemId : itemIds)
                {
                    int price = itemManager.getItemPriceWithSource(itemId, true);
                    if (price > 0)
                    {
                        prices.put(itemId, new PriceQuote(itemId, price, 0, retrievedAt, null));
                    }
                }

                future.complete(new PriceBook(retrievedAt, prices));
            }
            catch (RuntimeException ex)
            {
                future.completeExceptionally(ex);
            }
        });

        return future;
    }
}

