package com.bankstats.price;

import com.bankstats.model.PriceBook;
import java.util.Set;
import java.util.concurrent.CompletableFuture;
import javax.inject.Inject;
import javax.inject.Singleton;

@Singleton
public class WikiPriceProvider implements PriceProvider
{
    private final RuneLitePriceProvider delegate;
    private final PriceCache cache;

    @Inject
    public WikiPriceProvider(RuneLitePriceProvider delegate, PriceCache cache)
    {
        this.delegate = delegate;
        this.cache = cache;
    }

    @Override
    public CompletableFuture<PriceBook> getPrices(Set<Integer> itemIds)
    {
        PriceBook cached = cache.getIfFresh(itemIds);
        if (cached != null)
        {
            return CompletableFuture.completedFuture(cached);
        }

        return delegate.getPrices(itemIds).thenApply(priceBook ->
        {
            cache.put(priceBook);
            return priceBook;
        });
    }
}

