import java.awt.Color;
import java.awt.Component;
import java.text.DecimalFormat;
import javax.swing.JTable;
import javax.swing.table.DefaultTableCellRenderer;

public class BankStatsCellRenderer extends DefaultTableCellRenderer
{
    private static final DecimalFormat INTEGER_FORMAT = new DecimalFormat("#,##0");
    private static final DecimalFormat PERCENT_FORMAT = new DecimalFormat("+#,##0.00%;-#,##0.00%");

    @Override
    public Component getTableCellRendererComponent(
        JTable table,
        Object value,
        boolean isSelected,
        boolean hasFocus,
        int row,
        int column)
    {
        Component component = super.getTableCellRendererComponent(table, value, isSelected, hasFocus, row, column);
        int modelColumn = table.convertColumnIndexToModel(column);
        setHorizontalAlignment(value instanceof Number ? RIGHT : LEFT);

        if (value instanceof Long)
        {
            long amount = (Long) value;
            setText(INTEGER_FORMAT.format(amount));
            colorSignedValue(component, table, isSelected, amount, modelColumn);
        }
        else if (value instanceof Double)
        {
            double percent = (Double) value;
            setText(PERCENT_FORMAT.format(percent / 100.0));
            colorSignedValue(component, table, isSelected, percent, modelColumn);
        }
        else if (!isSelected)
        {
            component.setForeground(table.getForeground());
        }

        return component;
    }

    private void colorSignedValue(Component component, JTable table, boolean isSelected, double amount, int modelColumn)
    {
        if (isSelected)
        {
            component.setForeground(table.getSelectionForeground());
        }
        else if (amount > 0 && isSignedValueColumn(table, modelColumn))
        {
            component.setForeground(new Color(0, 150, 0));
        }
        else if (amount < 0 && isSignedValueColumn(table, modelColumn))
        {
            component.setForeground(new Color(190, 40, 40));
        }
        else
        {
            component.setForeground(table.getForeground());
        }
    }

    private boolean isSignedValueColumn(JTable table, int modelColumn)
    {
        String columnName = table.getModel().getColumnName(modelColumn);
        return "P/L".equals(columnName) || "Change".equals(columnName);
    }
}

package com.bankstats.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import javax.swing.JPanel;

public class BankStatsChartPanel extends JPanel
{
    private static final int MAX_BARS = 10;
    private static final int LEFT_PADDING = 96;
    private static final int RIGHT_PADDING = 16;
    private static final int TOP_PADDING = 24;
    private static final int BOTTOM_PADDING = 24;
    private static final Color GAIN_COLOR = new Color(68, 170, 90);
    private static final Color LOSS_COLOR = new Color(205, 80, 80);
    private static final Color ZERO_COLOR = new Color(130, 130, 130);

    private final List<BankStatsTableRow> rows = new ArrayList<>();
    private Color backgroundColor = new Color(30, 30, 30);
    private Color foregroundColor = new Color(220, 220, 220);
    private Color mutedForegroundColor = new Color(170, 170, 170);
    private Color axisColor = new Color(70, 70, 70);

    public BankStatsChartPanel()
    {
        setPreferredSize(new Dimension(320, 220));
        setMinimumSize(new Dimension(320, 160));
        setOpaque(true);
    }

    public void applyTheme(Color backgroundColor, Color foregroundColor, Color mutedForegroundColor, Color axisColor)
    {
        this.backgroundColor = backgroundColor;
        this.foregroundColor = foregroundColor;
        this.mutedForegroundColor = mutedForegroundColor;
        this.axisColor = axisColor;
        setBackground(backgroundColor);
        setForeground(foregroundColor);
        repaint();
    }

    public void setRows(List<BankStatsTableRow> newRows)
    {
        rows.clear();
        rows.addAll(selectChartRows(newRows));
        repaint();
    }

    public void clear()
    {
        rows.clear();
        repaint();
    }

    @Override
    protected void paintComponent(Graphics graphics)
    {
        super.paintComponent(graphics);
        Graphics2D g = (Graphics2D) graphics.create();
        try
        {
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            drawChart(g);
        }
        finally
        {
            g.dispose();
        }
    }

    private void drawChart(Graphics2D g)
    {
        int width = getWidth();
        int height = getHeight();
        FontMetrics metrics = g.getFontMetrics();

        Font originalFont = g.getFont();
        g.setFont(originalFont.deriveFont(Font.BOLD, 13f));
        metrics = g.getFontMetrics();
        g.setColor(foregroundColor);
        g.drawString("Top Analyzed Positions (" + rows.size() + " Rows)", 8, metrics.getAscent() + 4);
        g.setFont(originalFont);
        metrics = g.getFontMetrics();

        if (rows.isEmpty())
        {
            String message = "No item P/L to display yet.";
            int messageWidth = metrics.stringWidth(message);
            g.setColor(mutedForegroundColor);
            g.drawString(message, Math.max(8, (width - messageWidth) / 2), height / 2);
            return;
        }

        long maxAbsValue = 1;
        for (BankStatsTableRow row : rows)
        {
            maxAbsValue = Math.max(maxAbsValue, Math.abs(row.getPerformance().getTotalPositionChange()));
        }

        int chartTop = TOP_PADDING + metrics.getHeight();
        int chartBottom = height - BOTTOM_PADDING;
        int chartHeight = Math.max(1, chartBottom - chartTop);
        int barGap = 4;
        int barHeight = Math.max(8, (chartHeight - (rows.size() - 1) * barGap) / rows.size());
        int zeroX = LEFT_PADDING;
        int maxBarWidth = Math.max(1, width - LEFT_PADDING - RIGHT_PADDING);

        g.setColor(axisColor);
        g.drawLine(zeroX, chartTop, zeroX, chartBottom);

        for (int i = 0; i < rows.size(); i++)
        {
            BankStatsTableRow row = rows.get(i);
            long value = row.getPerformance().getTotalPositionChange();
            int y = chartTop + i * (barHeight + barGap);
            int barWidth = (int) Math.max(1, Math.round((Math.abs(value) / (double) maxAbsValue) * maxBarWidth));

            g.setColor(value > 0 ? GAIN_COLOR : value < 0 ? LOSS_COLOR : ZERO_COLOR);
            g.fillRect(zeroX, y, barWidth, barHeight);

            g.setColor(foregroundColor);
            String name = abbreviate(row.getItemName(), metrics, LEFT_PADDING - 8);
            g.drawString(name, 4, y + barHeight - 2);

            String label = formatGp(value);
            int labelX = Math.min(width - RIGHT_PADDING - metrics.stringWidth(label), zeroX + barWidth + 4);
            g.drawString(label, labelX, y + barHeight - 2);
        }
    }

    private List<BankStatsTableRow> selectChartRows(List<BankStatsTableRow> sourceRows)
    {
        List<BankStatsTableRow> chartRows = new ArrayList<>();
        for (BankStatsTableRow row : sourceRows)
        {
            if (row.getPerformance().getTotalPositionChange() != 0)
            {
                chartRows.add(row);
            }
        }

        chartRows.sort(Comparator
            .comparingLong((BankStatsTableRow row) -> Math.abs(row.getPerformance().getTotalPositionChange()))
            .reversed()
            .thenComparing(row -> row.getItemName().toLowerCase()));

        if (chartRows.size() > MAX_BARS)
        {
            return new ArrayList<>(chartRows.subList(0, MAX_BARS));
        }

        return chartRows;
    }

    private String abbreviate(String value, FontMetrics metrics, int maxWidth)
    {
        if (metrics.stringWidth(value) <= maxWidth)
        {
            return value;
        }

        String suffix = "...";
        for (int length = value.length() - 1; length > 0; length--)
        {
            String candidate = value.substring(0, length) + suffix;
            if (metrics.stringWidth(candidate) <= maxWidth)
            {
                return candidate;
            }
        }

        return suffix;
    }

    private String formatGp(long value)
    {
        long abs = Math.abs(value);
        String sign = value > 0 ? "+" : value < 0 ? "-" : "";

        if (abs >= 1_000_000_000L)
        {
            return String.format("%s%.2fb", sign, abs / 1_000_000_000.0);
        }

        if (abs >= 1_000_000L)
        {
            return String.format("%s%.2fm", sign, abs / 1_000_000.0);
        }

        if (abs >= 1_000L)
        {
            return String.format("%s%.1fk", sign, abs / 1_000.0);
        }

        return sign + abs;
    }
}

