    private final List<BankStatsTableRow> currentRows = new ArrayList<>();
    private Runnable createBaselineAction;
    private Runnable loadBankAction;
    private Runnable refreshPricesAction;

    @Inject
    public BankStatsPanel(ClientThread clientThread, ItemManager itemManager)
    {
        super(false);
        this.clientThread = clientThread;
        this.itemManager = itemManager;

        setLayout(new BorderLayout(5, 5));
        setBackground(BACKGROUND);
        add(createControls(), BorderLayout.NORTH);
        add(createResultsPanel(), BorderLayout.CENTER);
        add(createStatusPanel(), BorderLayout.SOUTH);

        configureTable(table, tableModel, 1);
        chartPanel.applyTheme(BACKGROUND, FOREGROUND, MUTED_FOREGROUND, GRID);

        progressBar.setStringPainted(true);
        progressBar.setVisible(false);
        showFullTableButton.setEnabled(false);

        styleLabel(stateLabel, true);
        styleLabel(baselineDateLabel, false);
        styleLabel(startValueLabel, false);
        styleLabel(currentValueLabel, false);
        styleLabel(diagnosticsLabel, false);
        styleButton(setBaselineButton, BASELINE_BUTTON);
        styleButton(loadBankButton, LOAD_BUTTON);
        styleButton(refreshButton, REFRESH_BUTTON);
        styleButton(showFullTableButton, DETAILS_BUTTON);
        styleButton(helpButton, HELP_BUTTON);

        setBaselineButton.addActionListener(event -> runIfPresent(createBaselineAction));
        loadBankButton.addActionListener(event -> runIfPresent(loadBankAction));
        refreshButton.addActionListener(event -> runIfPresent(refreshPricesAction));
        showFullTableButton.addActionListener(event -> showFullTablePopup());
        helpButton.addActionListener(event -> showHelpPopup());
    }

    public void setCreateBaselineAction(Runnable action)
    {
        createBaselineAction = action;
    }

    public void setLoadBankAction(Runnable action)
    {
        loadBankAction = action;
    }

    public void setRefreshPricesAction(Runnable action)
    {
        refreshPricesAction = action;
    }

    public boolean confirmOverwriteBaseline()
    {
        int result = JOptionPane.showConfirmDialog(
            this,
            "This will replace your current Bank Stats baseline with the items currently in your bank.",
            "Overwrite baseline?",
            JOptionPane.YES_NO_OPTION,
            JOptionPane.WARNING_MESSAGE);
        return result == JOptionPane.YES_OPTION;
    }

    public void setLoadState(LoadState state, String message)
    {
        if (SwingUtilities.isEventDispatchThread())
        {
            applyLoadState(state, message);
            return;
        }

        SwingUtilities.invokeLater(() -> applyLoadState(state, message));
    }

    public void showAnalysisReady(int rowCount)
    {
        setLoadState(LoadState.ANALYZING, "Analysis produced " + rowCount + " rows; updating display...");
        diagnosticsLabel.setText("Updating table and chart...");
    }

    public void displayAnalysis(BankAnalysis analysis)
    {
        long generation = displayGeneration.incrementAndGet();
        List<BankStatsTableRow> rows = new ArrayList<>();

        for (ItemPerformance performance : analysis.getRows())
        {
            rows.add(new BankStatsTableRow(getFallbackItemName(performance.getItemId()), performance));
        }

        setDisplayedRows(rows);
        baselineDateLabel.setText("Baseline: " + DATE_FORMATTER.format(analysis.getBaselineCreatedAt()));
        startValueLabel.setText(String.format("Start GP: %,d", analysis.getBaselineValue()));
        currentValueLabel.setText(String.format("Current GP: %,d", analysis.getCurrentValue()));
        setMarketProfitLossText(analysis.getMarketProfitLoss(), true);
        progressBar.setVisible(false);
        refreshButton.setEnabled(true);
        showFullTableButton.setEnabled(!rows.isEmpty());

        resolveItemNamesAsync(generation, rows, analysis);
    }

    public void showDisplayError(String message, BankAnalysis analysis)
    {
        int rows = analysis == null ? 0 : analysis.getRows().size();
        displayGeneration.incrementAndGet();
        currentRows.clear();
        tableModel.clear();
        chartPanel.clear();
        diagnosticsLabel.setText("Display error after analyzing " + rows + " rows: " + message);
        progressBar.setVisible(false);
        showFullTableButton.setEnabled(false);
    }

    public void clearAnalysis()
    {
        displayGeneration.incrementAndGet();
        currentRows.clear();
        tableModel.clear();
        chartPanel.clear();
        baselineDateLabel.setText("Baseline: none");
        startValueLabel.setText("Start GP: -");
        currentValueLabel.setText("Current GP: -");
        diagnosticsLabel.setText(" ");
        refreshButton.setEnabled(false);
        showFullTableButton.setEnabled(false);
        progressBar.setVisible(false);
    }

    private void setDisplayedRows(List<BankStatsTableRow> rows)
    {
        currentRows.clear();
        currentRows.addAll(rows);
        tableModel.setRows(rows);
        chartPanel.setRows(rows);
    }

    private void resolveItemNamesAsync(long generation, List<BankStatsTableRow> rows, BankAnalysis analysis)
    {
        List<BankStatsTableRow> snapshot = new ArrayList<>(rows);
        clientThread.invokeLater(() ->
        {
            List<BankStatsTableRow> namedRows = new ArrayList<>();
            for (BankStatsTableRow row : snapshot)
            {
                ItemPerformance performance = row.getPerformance();
                namedRows.add(new BankStatsTableRow(resolveItemName(performance.getItemId()), performance));
            }

            SwingUtilities.invokeLater(() ->
            {
                if (displayGeneration.get() != generation)
                {
                    return;
                }

                setDisplayedRows(namedRows);
                setMarketProfitLossText(analysis.getMarketProfitLoss(), false);
            });
        });
    }

    private void applyLoadState(LoadState state, String message)
    {
        stateLabel.setText(message == null || message.isEmpty() ? state.name() : message);
        updateProgressBar(state, message);
        boolean busy = state == LoadState.READING_BANK || state == LoadState.LOADING_PRICES || state == LoadState.ANALYZING;
        setBaselineButton.setEnabled(!busy);
        loadBankButton.setEnabled(!busy);
        refreshButton.setEnabled(!busy && tableModel.getRowCount() > 0);
        showFullTableButton.setEnabled(!busy && !currentRows.isEmpty());
    }

    private JPanel createControls()
    {
        JPanel panel = new JPanel(new BorderLayout(5, 5));
        panel.setBackground(BACKGROUND);
        JPanel buttons = new JPanel(new GridLayout(0, 1, 3, 3));
        buttons.setBackground(BACKGROUND);
        JPanel firstRow = new JPanel(new GridLayout(1, 2, 3, 3));
        firstRow.setBackground(BACKGROUND);
        firstRow.add(setBaselineButton);
        firstRow.add(loadBankButton);

        JPanel secondRow = new JPanel(new GridLayout(1, 3, 3, 3));
        secondRow.setBackground(BACKGROUND);
        secondRow.add(refreshButton);
        secondRow.add(showFullTableButton);
        secondRow.add(helpButton);

        buttons.add(firstRow);
        buttons.add(secondRow);
        panel.add(stateLabel, BorderLayout.NORTH);
        panel.add(buttons, BorderLayout.CENTER);
        return panel;
    }

    private JSplitPane createResultsPanel()
    {
        JScrollPane tableScrollPane = new JScrollPane(table);
        tableScrollPane.setBackground(TABLE_BACKGROUND);
        tableScrollPane.getViewport().setBackground(TABLE_BACKGROUND);
        tableScrollPane.setBorder(null);

        JSplitPane splitPane = new JSplitPane(JSplitPane.VERTICAL_SPLIT, chartPanel, tableScrollPane);
        splitPane.setResizeWeight(0.35);
        splitPane.setBorder(null);
        splitPane.setBackground(BACKGROUND);
        return splitPane;
    }
    private JPanel createStatusPanel()
    {
        JPanel panel = new JPanel(new GridLayout(0, 1, 3, 3));
        panel.setBackground(BACKGROUND);
        panel.add(progressBar);
        panel.add(baselineDateLabel);
        panel.add(startValueLabel);
        panel.add(currentValueLabel);
        panel.add(diagnosticsLabel);
        return panel;
    }

    private void showFullTablePopup()
    {
        BankStatsTableModel fullModel = new BankStatsTableModel(BankStatsTableModel.ViewMode.FULL);
        fullModel.setRows(currentRows);
        JTable fullTable = new JTable(fullModel);
        configureTable(fullTable, fullModel, 2);
        styleFullTablePopup(fullTable);

        JDialog dialog = new JDialog(SwingUtilities.getWindowAncestor(this), "Bank Stats full table");
        dialog.setDefaultCloseOperation(JDialog.DISPOSE_ON_CLOSE);
        JScrollPane scrollPane = new JScrollPane(fullTable);
        scrollPane.getViewport().setBackground(TABLE_BACKGROUND);
        dialog.add(scrollPane, BorderLayout.CENTER);
        dialog.setPreferredSize(new Dimension(900, 600));
        dialog.pack();
        dialog.setLocationRelativeTo(this);
        dialog.setVisible(true);
    }

    private void showHelpPopup()
    {
        JTextArea helpText = new JTextArea(HELP_TEXT);
        helpText.setEditable(false);
        helpText.setLineWrap(true);
        helpText.setWrapStyleWord(true);
        helpText.setBackground(PANEL_BACKGROUND);
        helpText.setForeground(FOREGROUND);
        helpText.setCaretColor(FOREGROUND);
        helpText.setFont(helpText.getFont().deriveFont(Font.PLAIN, 13f));
        helpText.setBorder(javax.swing.BorderFactory.createEmptyBorder(12, 12, 12, 12));

        JDialog dialog = new JDialog(SwingUtilities.getWindowAncestor(this), "Bank Stats Help");
        dialog.setDefaultCloseOperation(JDialog.DISPOSE_ON_CLOSE);
        dialog.add(helpText, BorderLayout.CENTER);
        dialog.setPreferredSize(new Dimension(420, 320));
        dialog.pack();
        dialog.setLocationRelativeTo(this);
        dialog.setVisible(true);
    }

    private void configureTable(JTable targetTable, BankStatsTableModel model, int sortColumn)
    {
        TableRowSorter<BankStatsTableModel> sorter = new TableRowSorter<>(model);
        targetTable.setRowSorter(sorter);
        sorter.setSortKeys(List.of(new RowSorter.SortKey(sortColumn, SortOrder.DESCENDING)));
        targetTable.setDefaultRenderer(Object.class, new BankStatsCellRenderer());
        targetTable.setDefaultRenderer(Long.class, new BankStatsCellRenderer());
        targetTable.setDefaultRenderer(Double.class, new BankStatsCellRenderer());
        targetTable.setBackground(TABLE_BACKGROUND);
        targetTable.setForeground(FOREGROUND);
        targetTable.setGridColor(GRID);
        targetTable.setSelectionBackground(new Color(60, 80, 110));
        targetTable.setSelectionForeground(Color.WHITE);
        targetTable.setFont(targetTable.getFont().deriveFont(Font.PLAIN, 12f));
        targetTable.setRowHeight(22);
        JTableHeader header = targetTable.getTableHeader();
        header.setBackground(PANEL_BACKGROUND);
        header.setForeground(FOREGROUND);
        header.setFont(header.getFont().deriveFont(Font.BOLD, 12f));
    }

    private void styleFullTablePopup(JTable fullTable)
    {
        fullTable.setFont(fullTable.getFont().deriveFont(Font.PLAIN, 15f));
        fullTable.setRowHeight(28);
        JTableHeader header = fullTable.getTableHeader();
        header.setFont(header.getFont().deriveFont(Font.BOLD, 15f));
    }

    private void updateProgressBar(LoadState state, String message)
    {
        if (state == LoadState.ANALYZING)
        {
            AnalysisProgress progress = AnalysisProgress.parse(message);
            progressBar.setVisible(true);
            progressBar.setIndeterminate(progress == null || progress.totalItems == 0);

            if (progress != null && progress.totalItems > 0)
            {
                progressBar.setMinimum(0);
                progressBar.setMaximum(progress.totalItems);
                progressBar.setValue(progress.analyzedItems);
                progressBar.setString(String.format("%,d / %,d analyzed, %,d left", progress.analyzedItems, progress.totalItems, progress.remainingItems));
            }
            else
            {
                progressBar.setString("Analyzing bank...");
            }
            return;
        }

        boolean busy = state == LoadState.READING_BANK || state == LoadState.LOADING_PRICES;
        progressBar.setVisible(busy);
        progressBar.setIndeterminate(busy);
        progressBar.setString(message == null || message.isEmpty() ? state.name() : message);
    }

    private String resolveItemName(int itemId)
    {
        try
        {
            String name = itemManager.getItemComposition(itemId).getName();
            if (name != null && !name.isEmpty())
            {
                return name;
            }
        }
        catch (RuntimeException ignored)
        {
            // Fall through to ID fallback.
        }

        return getFallbackItemName(itemId);
    }

    private String getFallbackItemName(int itemId)
    {
        return "Item " + itemId;
    }

    private void styleLabel(JLabel label, boolean prominent)
    {
        label.setForeground(prominent ? FOREGROUND : MUTED_FOREGROUND);
        label.setFont(label.getFont().deriveFont(prominent ? Font.BOLD : Font.PLAIN, 12f));
    }

    private void styleButton(JButton button, Color background)
    {
        Color hoverBackground = background.brighter();
        Color pressedBackground = background.darker();
        button.setBackground(background);
        button.setForeground(Color.WHITE);
        button.setBorder(javax.swing.BorderFactory.createLineBorder(GRID));
        button.setFocusPainted(false);
        button.setOpaque(true);
        button.setFont(button.getFont().deriveFont(Font.BOLD, 12f));
        button.addPropertyChangeListener("enabled", event -> button.setBackground(background));
        button.addMouseListener(new MouseAdapter()
        {
            @Override
            public void mouseEntered(MouseEvent event)
            {
                if (button.isEnabled())
                {
                    button.setBackground(hoverBackground);
                }
            }

            @Override
            public void mouseExited(MouseEvent event)
            {
                button.setBackground(background);
            }

            @Override
            public void mousePressed(MouseEvent event)
            {
                if (button.isEnabled())
                {
                    button.setBackground(pressedBackground);
                }
            }

            @Override
            public void mouseReleased(MouseEvent event)
            {
                button.setBackground(button.isEnabled() && button.contains(event.getPoint()) ? hoverBackground : background);
            }
        });
    }

    private void setMarketProfitLossText(long marketProfitLoss, boolean resolvingNames)
    {
        diagnosticsLabel.setText(String.format(
            "<html>Market P/L: <font color=\"%s\">%s</font>%s</html>",
            getProfitLossColor(marketProfitLoss),
            formatSignedGp(marketProfitLoss),
            resolvingNames ? " | Resolving names..." : ""));
    }

    private String getProfitLossColor(long value)
    {
        Color color = value > 0 ? PROFIT_COLOR : value < 0 ? LOSS_COLOR : MUTED_FOREGROUND;
        return String.format("#%02x%02x%02x", color.getRed(), color.getGreen(), color.getBlue());
    }

    private String formatSignedGp(long value)
    {
        if (value == 0)
        {
            return "0";
        }

        return String.format("%+,d", value);
    }

    private void runIfPresent(Runnable runnable)
    {
        if (runnable != null)
        {
            runnable.run();
        }
    }

    private static class AnalysisProgress
    {
        private final int analyzedItems;
        private final int totalItems;
        private final int remainingItems;

        private AnalysisProgress(int analyzedItems, int totalItems, int remainingItems)
        {
            this.analyzedItems = analyzedItems;
            this.totalItems = totalItems;
            this.remainingItems = remainingItems;
        }

        private static AnalysisProgress parse(String message)
        {
            if (message == null || !message.startsWith(ANALYZING_PREFIX))
            {
                return null;
            }

            String digits = message.replaceAll("[^0-9 ]", " ").trim().replaceAll(" +", " ");
            if (digits.isEmpty())
            {
                return null;
            }

            String[] parts = digits.split(" ");
            if (parts.length < 3)
            {
                return null;
            }

            return new AnalysisProgress(Integer.parseInt(parts[0]), Integer.parseInt(parts[1]), Integer.parseInt(parts[2]));
        }
    }
}

package com.bankstats.ui;

import com.bankstats.model.ItemPerformance;
import java.util.ArrayList;
import java.util.List;
import javax.swing.table.AbstractTableModel;

public class BankStatsTableModel extends AbstractTableModel
{
    public enum ViewMode
    {
        COMPACT,
        FULL
    }

    private static final String[] COMPACT_COLUMNS = {"Item", "P/L"};
    private static final String[] FULL_COLUMNS = {"Item", "Qty", "P/L", "Start Price", "Current Price", "Change", "Status"};

    private final ViewMode viewMode;
    private final List<BankStatsTableRow> rows = new ArrayList<>();

    public BankStatsTableModel()
    {
        this(ViewMode.FULL);
    }

    public BankStatsTableModel(ViewMode viewMode)
    {
        this.viewMode = viewMode;
    }

    public void setRows(List<BankStatsTableRow> newRows)
    {
        rows.clear();
        rows.addAll(newRows);
        fireTableDataChanged();
    }

    public void clear()
    {
        rows.clear();
        fireTableDataChanged();
    }

    @Override
    public int getRowCount()
    {
        return rows.size();
    }

    @Override
    public int getColumnCount()
    {
        return getColumns().length;
    }

    @Override
    public String getColumnName(int column)
    {
        return getColumns()[column];
    }

    @Override
    public Class<?> getColumnClass(int columnIndex)
    {
        if (viewMode == ViewMode.COMPACT)
        {
            return columnIndex == 1 ? Long.class : String.class;
        }

        if (columnIndex == 5)
        {
            return Double.class;
        }

        if (columnIndex >= 1 && columnIndex <= 4)
        {
            return Long.class;
        }

        return String.class;
    }

    @Override
    public Object getValueAt(int rowIndex, int columnIndex)
    {
        BankStatsTableRow row = rows.get(rowIndex);
        ItemPerformance performance = row.getPerformance();

        if (viewMode == ViewMode.COMPACT)
        {
            switch (columnIndex)
            {
                case 0:
                    return row.getItemName();
                case 1:
                    return performance.getTotalPositionChange();
                default:
                    throw new IllegalArgumentException("Unknown Bank Stats compact column: " + columnIndex);
            }
        }

        switch (columnIndex)
        {
            case 0:
                return row.getItemName();
            case 1:
                return performance.getCurrentQuantity();
            case 2:
                return performance.getTotalPositionChange();
            case 3:
                return performance.getBaselineUnitPrice();
            case 4:
                return performance.getCurrentUnitPrice();
            case 5:
                return performance.getPercentPriceChange();
            case 6:
                return performance.getPriceStatus().name();
            default:
                throw new IllegalArgumentException("Unknown Bank Stats full column: " + columnIndex);
        }
    }

    private String[] getColumns()
    {
        return viewMode == ViewMode.COMPACT ? COMPACT_COLUMNS : FULL_COLUMNS;
    }
}

